// <<<VYBE:PRESET_DEFS>>> — regenerated by apply_presets_to_source()
void ADPCMDecayProcessor::setCurrentProgram(int index)
{
    if (index < 0 || index >= kNumFactoryPresets) return;
    currentProgram = index;
    presetManager.loadPreset(index);
}

int ADPCMDecayProcessor::getCurrentProgram()
{
    // Track PresetManager, which the plugin's own browser also drives — but only
    // while it sits on a FACTORY preset. The host program menu exposes the factory
    // bank alone (a count that grows when a musician saves a patch breaks hosts that
    // cache it), so a user patch reports the last factory index rather than an index
    // the host would reject as out of range.
    const int i = presetManager.getCurrentIndex();
    return (i >= 0 && i < kNumFactoryPresets) ? i : currentProgram;
}

const juce::String ADPCMDecayProcessor::getProgramName(int index)
{
    return (index >= 0 && index < kNumFactoryPresets)
         ? juce::String(kFactoryPresets[index].name) : juce::String();
}
// <<<VYBE:PRESET_DEFS:END>>>

void ADPCMDecayProcessor::prepareToPlay(double sampleRate, int samplesPerBlock)
{
    vybecode::ModuleSpec spec;
    spec.sampleRate = sampleRate;
    spec.maxBlockSize = samplesPerBlock;
    spec.numChannels = getTotalNumOutputChannels();

    input.prepare(spec);
    input.reset();
    encode.prepare(spec);
    encode.reset();
    decode.prepare(spec);
    decode.reset();
    saturation.prepare(spec);
    saturation.reset();
    filter.prepare(spec);
    filter.reset();
    quantization.prepare(spec);
    quantization.reset();
    corruption.prepare(spec);
    corruption.reset();
    leakage.prepare(spec);
    leakage.reset();
    output.prepare(spec);
    output.reset();
    mix.prepare(spec);
    mix.reset();

    modMatrix.prepare(spec.sampleRate);
    setLatencySamples(input.getLatencySamples() + encode.getLatencySamples() + decode.getLatencySamples() + saturation.getLatencySamples() + filter.getLatencySamples() + quantization.getLatencySamples() + corruption.getLatencySamples() + leakage.getLatencySamples() + output.getLatencySamples() + mix.getLatencySamples());

    dcBlockX1_[0] = dcBlockX1_[1] = dcBlockY1_[0] = dcBlockY1_[1] = 0.0f;
}

void ADPCMDecayProcessor::releaseResources() {}

bool ADPCMDecayProcessor::isBusesLayoutSupported(const BusesLayout& layouts) const
{
#if JucePlugin_IsMidiEffect
    juce::ignoreUnused(layouts);
    return true;
#else
    if (layouts.getMainOutputChannelSet() != juce::AudioChannelSet::mono()
     && layouts.getMainOutputChannelSet() != juce::AudioChannelSet::stereo())
        return false;
#if ! JucePlugin_IsSynth
    if (layouts.getMainOutputChannelSet() != layouts.getMainInputChannelSet())
        return false;
#endif
    return true;
#endif
}

void ADPCMDecayProcessor::processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages)
{
    juce::ScopedNoDenormals noDenormals;

    auto totalNumInputChannels  = getTotalNumInputChannels();
    auto totalNumOutputChannels = getTotalNumOutputChannels();

    for (auto i = totalNumInputChannels; i < totalNumOutputChannels; ++i)
        buffer.clear(i, 0, buffer.getNumSamples());

    juce::ignoreUnused(midiMessages);

    // Update all module parameters from APVTS
    input.updateFromAPVTS(apvts, "input_");
    encode.updateFromAPVTS(apvts, "encode_");
    decode.updateFromAPVTS(apvts, "decode_");
    saturation.updateFromAPVTS(apvts, "saturation_");
    filter.updateFromAPVTS(apvts, "filter_");
    quantization.updateFromAPVTS(apvts, "quantization_");
    corruption.updateFromAPVTS(apvts, "corruption_");
    leakage.updateFromAPVTS(apvts, "leakage_");
    output.updateFromAPVTS(apvts, "output_");
    mix.updateFromAPVTS(apvts, "mix_");


    // Runtime modulation matrix (Layer B): advance sources, route into destinations.
    modMatrix.processMidi(midiMessages);
    modMatrix.process(buffer.getNumSamples());
    corruption.setModulation("amp_jitter", 0.4f * modMatrix.getDestModulation(0));
    corruption.setModulation("density", 0.5f * modMatrix.getDestModulation(1));
    corruption.setModulation("lowpass", 0.5f * modMatrix.getDestModulation(2));
    corruption.setModulation("polarity", 0.4f * modMatrix.getDestModulation(3));
    decode.setModulation("bit_depth", 0.4f * modMatrix.getDestModulation(4));
    decode.setModulation("mix", 0.4f * modMatrix.getDestModulation(5));
    decode.setModulation("sample_rate_reduction", 0.4f * modMatrix.getDestModulation(6));
    encode.setModulation("bit_depth", 0.4f * modMatrix.getDestModulation(7));
    encode.setModulation("mix", 0.4f * modMatrix.getDestModulation(8));
    encode.setModulation("sample_rate_reduction", 0.4f * modMatrix.getDestModulation(9));
    filter.setModulation("cutoff", 0.5f * modMatrix.getDestModulation(10));
    filter.setModulation("order", 0.4f * modMatrix.getDestModulation(11));
    input.setModulation("gain_db", 0.5f * modMatrix.getDestModulation(12));
    leakage.setModulation("depth", 0.4f * modMatrix.getDestModulation(13));
    leakage.setModulation("rate", 0.5f * modMatrix.getDestModulation(14));
    leakage.setModulation("smoothness", 0.4f * modMatrix.getDestModulation(15));
    mix.setModulation("mix", 0.4f * modMatrix.getDestModulation(16));
    output.setModulation("gain_db", 0.5f * modMatrix.getDestModulation(17));
    quantization.setModulation("color", 0.4f * modMatrix.getDestModulation(18));
    quantization.setModulation("level", 0.4f * modMatrix.getDestModulation(19));
    saturation.setModulation("asymmetry", 0.4f * modMatrix.getDestModulation(20));
    saturation.setModulation("drive_db", 0.5f * modMatrix.getDestModulation(21));
    saturation.setModulation("output_db", 0.5f * modMatrix.getDestModulation(22));
    // Apply this block's modulation to every parameter shadow.
    input.refreshShadows();
    encode.refreshShadows();
    decode.refreshShadows();
    saturation.refreshShadows();
    filter.refreshShadows();
    quantization.refreshShadows();
    corruption.refreshShadows();
    leakage.refreshShadows();
    output.refreshShadows();
    mix.refreshShadows();

    // Process audio through module chain
    mix.captureDryInput(buffer);  // D6: feed the pre-chain dry to the mixer
    input.process(buffer);
    encode.process(buffer);
    decode.process(buffer);
    saturation.process(buffer);
    filter.process(buffer);
    quantization.process(buffer);
    corruption.process(buffer);
    leakage.process(buffer);
    output.process(buffer);
    mix.process(buffer);


    // ── Output DC-blocker (~4 Hz high-pass, per channel) ──
    {
        const float dcR = 0.9995f;
        const int dcNch = juce::jmin(buffer.getNumChannels(), 2);
        const int dcN = buffer.getNumSamples();
        for (int dcCh = 0; dcCh < dcNch; ++dcCh)
        {
            float* dcData = buffer.getWritePointer(dcCh);
            float x1 = dcBlockX1_[dcCh], y1 = dcBlockY1_[dcCh];
            for (int s = 0; s < dcN; ++s)
            {
                const float x = dcData[s];
                const float y = x - x1 + dcR * y1;
                x1 = x; y1 = y;
                dcData[s] = y;
            }
            dcBlockX1_[dcCh] = x1;
            dcBlockY1_[dcCh] = y1;
        }
    }
}

