void ADPCMDecayProcessor::getStateInformation(juce::MemoryBlock& destData)
{
    auto state = apvts.copyState();
    // Carry which patch is selected alongside the parameter values. Without it the plugin
    // reopens a saved session reporting preset #1 while the knobs hold the session's real
    // values — a desync every host displays. Stored as a CHILD of the parameter state, so an
    // older session (which has no such child) still loads: restoreState() simply no-ops.
    state.appendChild(presetManager.getState(), nullptr);
    std::unique_ptr<juce::XmlElement> xml(state.createXml());
    copyXmlToBinary(*xml, destData);
}

void ADPCMDecayProcessor::setStateInformation(const void* data, int sizeInBytes)
{
    std::unique_ptr<juce::XmlElement> xml(getXmlFromBinary(data, sizeInBytes));
    if (xml == nullptr || !xml->hasTagName(apvts.state.getType()))
        return;

    auto tree = juce::ValueTree::fromXml(*xml);

    // Lift our child out before handing the tree to the APVTS: replaceState() adopts the whole
    // tree, and leaving a foreign child inside the parameter state would round-trip it back into
    // every subsequent save, nesting one deeper each time.
    auto presetState = tree.getChildWithName(vybecode::PresetManager::getStateTag());
    if (presetState.isValid())
        tree.removeChild(presetState, nullptr);

    apvts.replaceState(tree);
    presetManager.restoreState(presetState);   // selection only — the values are already restored
}

